5	namespace App\Models;
6	
7	use AtrioTeam\DigitalHub\Assets\Concerns\HasAssets;
8	use AtrioTeam\DigitalHub\Assets\Contracts\OwnsAssets;
9	use AtrioTeam\DigitalHub\Identity\Concerns\HasGlobalId;
10	use AtrioTeam\DigitalHub\Pim\AttributeSchema;
11	use AtrioTeam\DigitalHub\Pim\Concerns\HasTechnicalAttributes;
12	use AtrioTeam\DigitalHub\Tags\Models\Tag;
13	use Illuminate\Database\Eloquent\Model;
14	use Illuminate\Database\Eloquent\Relations\BelongsTo;
15	use Illuminate\Database\Eloquent\Relations\BelongsToMany;
16	use Illuminate\Database\Eloquent\Relations\HasMany;
17	use InvalidArgumentException;
18	use Spatie\MediaLibrary\HasMedia;
19	use Spatie\Tags\HasTags;
20	use Spatie\Translatable\Attributes\Translatable;
21	use Spatie\Translatable\HasTranslations;
22	
23	#[Translatable('name')]
24	class Product extends Model implements HasMedia, OwnsAssets
25	{
26	    use HasAssets;
27	    use HasGlobalId;
28	    use HasTags;
29	    use HasTechnicalAttributes;
30	    use HasTranslations;
31	
32	    protected $guarded = [];
33	
34	    protected static function booted(): void
35	    {
36	        // strategia orfani (opzione C, design §3.6): al salvataggio rimuove dal JSON
37	        // degli attributi le chiavi non più previste dallo schema corrente (risolto
38	        // dalla tipologia già assegnata sul record). L'utente è avvisato a monte
39	        // dall'alert inline nel ProductForm; qui avviene lo strip effettivo.
40	        static::saving(function (self $product): void {
41	            // se la tipologia è cambiata, la relazione productType potrebbe essere
42	            // ancora quella vecchia in cache: la scarico così lo schema viene
43	            // risolto dalla tipologia appena assegnata.
44	            if ($product->isDirty('product_type_id')) {
45	                $product->unsetRelation('productType');
46	            }
47	
48	            $product->setAttribute(
49	                $product->attributesColumn(),
50	                $product->stripOrphanAttributes($product->attributeSchema()),
51	            );
52	        });
53	    }
54	
55	    /**
56	     * Lo schema attributi del Product è determinato dalla ProductType associata.
57	     * Se la ProductType non ha uno schema configurato, il prodotto non ha attributi tipizzati.
58	     */
59	    public function resolveAttributeSchemaClass(): ?string
60	    {
61	        $class = $this->productType?->attribute_schema_class;
62	
63	        return is_string($class) && is_subclass_of($class, AttributeSchema::class) ? $class : null;
64	    }
65	
66	
67	    /**
68	     * Nome comprensivo del nome collezione (category2)
69	     */
70	    public function catalogName(?string $locale = null): string
71	    {
72	        $locale ??= app()->getLocale();
73	        // @phpstan-ignore binaryOp.invalid,binaryOp.invalid
74	        return $this->category2?->getTranslation('name', $locale)
75	            . ' ' . $this->getTranslation('name', $locale);
76	    }
77	
78	    /**
79	     * Padre nella composizione (il "divano modulare" wrapper). Null per i
80	     * prodotti non componibili e per gli stessi wrapper.
81	     *
82	     * @return BelongsTo<Product, $this>
83	     */
84	    public function parent(): BelongsTo
85	    {
86	        return $this->belongsTo(self::class, 'parent_id');
87	    }
88	
89	    /**
90	     * I moduli che compongono questo prodotto (adjacency list).
91	     *
92	     * @return HasMany<Product, $this>
93	     */
94	    public function modules(): HasMany
95	    {
96	        return $this->hasMany(self::class, 'parent_id');
97	    }
98	
99	    /**
100	     * @return BelongsTo<Category2, $this>
101	     */
102	    public function category2(): BelongsTo
103	    {
104	        return $this->belongsTo(Category2::class, 'category_2_id');
105	    }
106	
107	    /**
108	     * @return BelongsTo<ProductType, $this>
109	     */
110	    public function productType(): BelongsTo
111	    {
112	        return $this->belongsTo(ProductType::class);
113	    }
114	
115	    /**
116	     * Materiali (finiture dure) del prodotto (singola finitura).
117	     *
118	     * @return BelongsToMany<Material, $this>
119	     */
120	    public function materials(): BelongsToMany
121	    {
122	        return $this->belongsToMany(Material::class, 'material_product', 'product_id', 'material_id');
123	    }
124	
125	    /**
126	     * Materiali assegnati al prodotto che, tra i loro tag, ne hanno uno con il
127	     * dato valore sull'asse "finalità" (es. struttura, piano_tavolo, ...).
128	     *
129	     * @return BelongsToMany<Material, $this>
130	     */
131	    public function materialsForFinalita(string $value): BelongsToMany
132	    {
133	        $tags = Tag::query()->withMeta('info_prodotto:finalita', $value)->get();
134	
135	        if ($tags->isEmpty()) {
136	            throw new InvalidArgumentException("Nessun tag trovato per info_prodotto:finalita = \"{$value}\"");
137	        }
138	
139	        return $this->materials()->withAnyTags($tags);
140	    }
141	
142	    /**
143	     * Tessuti rivestibili (singolo colore).
144	     *
145	     * @return BelongsToMany<Fabric, $this>
146	     */
147	    public function fabrics(): BelongsToMany
148	    {
149	        return $this->belongsToMany(Fabric::class, 'fabric_product', 'product_id', 'fabric_id');
150	    }
151	
152	    /**
153	     * @return BelongsToMany<Environment, $this>
154	     */
155	    public function environments(): BelongsToMany
156	    {
157	        return $this->belongsToMany(Environment::class, 'environment_product', 'product_id', 'environment_id');
158	    }
159	}
