3	namespace Filament\Resources\Resource\Concerns;
4	
5	use Filament\Actions\Action;
6	use Filament\Facades\Filament;
7	use Filament\GlobalSearch\GlobalSearchResult;
8	use Illuminate\Contracts\Support\Htmlable;
9	use Illuminate\Database\Connection;
10	use Illuminate\Database\Eloquent\Builder;
11	use Illuminate\Database\Eloquent\Model;
12	use Illuminate\Support\Arr;
13	use Illuminate\Support\Collection;
14	use ReflectionProperty;
15	
16	use function Filament\Support\generate_search_column_expression;
17	use function Filament\Support\generate_search_term_expression;
18	
19	/**
20	 * @template TModel of Model = Model
21	 */
22	trait HasGlobalSearch
23	{
24	    protected static int $globalSearchResultsLimit = 50;
25	
26	    protected static ?bool $isGlobalSearchForcedCaseInsensitive = null;
27	
28	    protected static ?bool $shouldSplitGlobalSearchTerms = null;
29	
30	    protected static bool $isGloballySearchable = true;
31	
32	    protected static ?int $globalSearchSort = null;
33	
34	    public static function canGloballySearch(): bool
35	    {
36	        $isGloballySearchable = static::$isGloballySearchable;
37	
38	        if (
39	            $isGloballySearchable &&
40	            Filament::getCurrentOrDefaultPanel()?->isGlobalSearchResourceOptIn()
41	        ) {
42	            $isGloballySearchable = (new ReflectionProperty(static::class, 'isGloballySearchable'))
43	                ->getDeclaringClass()
44	                ->getName() === static::class;
45	        }
46	
47	        return $isGloballySearchable && count(static::getGloballySearchableAttributes()) && static::canAccess();
48	    }
49	
50	    /**
51	     * @return array<string>
52	     */
53	    public static function getGloballySearchableAttributes(): array
54	    {
55	        $titleAttribute = static::getRecordTitleAttribute();
56	
57	        if ($titleAttribute === null) {
58	            return [];
59	        }
60	
61	        return [$titleAttribute];
62	    }
63	
64	    /**
65	     * @return array<Action>
66	     */
67	    public static function getGlobalSearchResultActions(Model $record): array
68	    {
69	        return [];
70	    }
71	
72	    /**
73	     * @return array<string, string>
74	     */
75	    public static function getGlobalSearchResultDetails(Model $record): array
76	    {
77	        return [];
78	    }
79	
80	    public static function getGlobalSearchResultTitle(Model $record): string | Htmlable
81	    {
82	        return static::getRecordTitle($record);
83	    }
84	
85	    public static function getGlobalSearchResultUrl(Model $record): ?string
86	    {
87	        // In the future, Filament will support global search in nested resources.
88	        // For now, you must specify custom global search result URLs to do so,
89	        // since there are missing URL parameters from the parent records.
90	        if (static::getParentResourceRegistration()) {
91	            return null;
92	        }
93	
94	        $canView = static::canView($record);
95	
96	        if (static::hasPage('view') && $canView) {
97	            return static::getUrl('view', ['record' => $record]);
98	        }
99	
100	        $canEdit = static::canEdit($record);
101	
102	        if (static::hasPage('edit') && $canEdit) {
103	            return static::getUrl('edit', ['record' => $record]);
104	        }
105	
106	        if ($canView) {
107	            return static::getUrl(parameters: [
108	                'tableAction' => 'view',
109	                'tableActionRecord' => $record,
110	            ]);
111	        }
112	
113	        if ($canEdit) {
114	            return static::getUrl(parameters: [
115	                'tableAction' => 'edit',
116	                'tableActionRecord' => $record,
117	            ]);
118	        }
119	
120	        return null;
121	    }
122	
123	    public static function getGlobalSearchResultsLimit(): int
124	    {
125	        return static::$globalSearchResultsLimit;
126	    }
127	
128	    public static function modifyGlobalSearchQuery(Builder $query, string $search): void {}
129	
130	    public static function getGlobalSearchResults(string $search): Collection
131	    {
132	        $query = static::getGlobalSearchEloquentQuery();
133	
134	        static::applyGlobalSearchAttributeConstraints($query, $search);
135	
136	        static::modifyGlobalSearchQuery($query, $search);
137	
138	        return $query
139	            ->limit(static::getGlobalSearchResultsLimit())
140	            ->get()
141	            ->map(function (Model $record): ?GlobalSearchResult {
142	                $url = static::getGlobalSearchResultUrl($record);
143	
144	                if (blank($url)) {
145	                    return null;
146	                }
147	
148	                return new GlobalSearchResult(
149	                    title: static::getGlobalSearchResultTitle($record),
150	                    url: $url,
151	                    details: static::getGlobalSearchResultDetails($record),
152	                    actions: array_map(
153	                        fn (Action $action) => $action->hasRecord() ? $action : $action->record($record),
154	                        static::getGlobalSearchResultActions($record),
155	                    ),
156	                );
157	            })
158	            ->filter();
159	    }
160	
161	    public static function isGlobalSearchForcedCaseInsensitive(): ?bool
162	    {
163	        return static::$isGlobalSearchForcedCaseInsensitive;
164	    }
165	
166	    public static function shouldSplitGlobalSearchTerms(): bool
167	    {
168	        return static::$shouldSplitGlobalSearchTerms ?? true;
169	    }
170	
171	    protected static function applyGlobalSearchAttributeConstraints(Builder $query, string $search): void
172	    {
173	        /** @var Connection $databaseConnection */
174	        $databaseConnection = $query->getConnection();
175	
176	        $search = generate_search_term_expression($search, static::isGlobalSearchForcedCaseInsensitive(), $databaseConnection);
177	
178	        if (! static::shouldSplitGlobalSearchTerms()) {
179	            $query->where(function (Builder $query) use ($search): void {
180	                $isFirst = true;
181	
182	                foreach (static::getGloballySearchableAttributes() as $attributes) {
183	                    static::applyGlobalSearchAttributeConstraint(
184	                        query: $query,
185	                        search: $search,
186	                        searchAttributes: Arr::wrap($attributes),
187	                        isFirst: $isFirst,
188	                    );
189	                }
190	            });
191	
192	            return;
193	        }
194	
195	        $searchWords = array_filter(
196	            str_getcsv(preg_replace('/(\s|\x{3164}|\x{1160})+/u', ' ', $search), separator: ' ', escape: '\\'),
197	            fn ($word): bool => filled($word),
198	        );
199	
200	        foreach ($searchWords as $searchWord) {
201	            $query->where(function (Builder $query) use ($searchWord): void {
202	                $isFirst = true;
203	
204	                foreach (static::getGloballySearchableAttributes() as $attributes) {
205	                    static::applyGlobalSearchAttributeConstraint(
206	                        query: $query,
207	                        search: $searchWord,
208	                        searchAttributes: Arr::wrap($attributes),
209	                        isFirst: $isFirst,
210	                    );
211	                }
212	            });
213	        }
214	    }
215	
216	    /**
217	     * @param  array<string>  $searchAttributes
218	     */
219	    protected static function applyGlobalSearchAttributeConstraint(Builder $query, string $search, array $searchAttributes, bool &$isFirst): Builder
220	    {
221	        $isForcedCaseInsensitive = static::isGlobalSearchForcedCaseInsensitive();
222	
223	        /** @var Connection $databaseConnection */
224	        $databaseConnection = $query->getConnection();
225	
226	        foreach ($searchAttributes as $searchAttribute) {
227	            $whereClause = $isFirst ? 'where' : 'orWhere';
228	
229	            $query->when(
230	                str($searchAttribute)->contains('.'),
231	                function (Builder $query) use ($databaseConnection, $isForcedCaseInsensitive, $searchAttribute, $search, $whereClause): Builder {
232	                    return $query->{"{$whereClause}Has"}(
233	                        (string) str($searchAttribute)->beforeLast('.'),
234	                        fn (Builder $query) => $query->where(
235	                            generate_search_column_expression($query->qualifyColumn((string) str($searchAttribute)->afterLast('.')), $isForcedCaseInsensitive, $databaseConnection),
236	                            'like',
237	                            "%{$search}%",
238	                        ),
239	                    );
240	                },
241	                fn (Builder $query) => $query->{$whereClause}(
242	                    generate_search_column_expression($query->qualifyColumn($searchAttribute), $isForcedCaseInsensitive, $databaseConnection),
243	                    'like',
244	                    "%{$search}%",
245	                ),
246	            );
247	
248	            $isFirst = false;
249	        }
250	
251	        return $query;
252	    }
253	
254	    /**
255	     * @return Builder<TModel>
256	     */
257	    public static function getGlobalSearchEloquentQuery(): Builder
258	    {
259	        return static::getEloquentQuery();
260	    }
261	
262	    public static function getGlobalSearchSort(): ?int
263	    {
264	        return static::$globalSearchSort;
265	    }
266	
267	    public static function globalSearchSort(?int $sort): void
268	    {
269	        static::$globalSearchSort = $sort;
270	    }
271	}
