10	    public function getResults(string $query): ?GlobalSearchResults
11	    {
12	        $builder = GlobalSearchResults::make();
13	
14	        $resources = Filament::getResources();
15	
16	        usort(
17	            $resources,
18	            fn (string $a, string $b): int => ($a::getGlobalSearchSort() ?? 0) <=> ($b::getGlobalSearchSort() ?? 0),
19	        );
20	
21	        foreach ($resources as $resource) {
22	            if (! $resource::canGloballySearch()) {
23	                continue;
24	            }
