3	namespace Filament\Resources\Resource\Concerns;
4	
5	use Filament\Facades\Filament;
6	use Illuminate\Database\Eloquent\Model;
7	use LogicException;
8	
9	use function Filament\Support\original_request;
10	
11	trait CanGenerateUrls
12	{
13	    /**
14	     * @param  array<mixed>  $parameters
15	     */
16	    public static function getUrl(?string $name = null, array $parameters = [], bool $isAbsolute = true, ?string $panel = null, ?Model $tenant = null, bool $shouldGuessMissingParameters = false, ?string $configuration = null): string
17	    {
18	        if (filled($configuration)) {
19	            return static::withConfiguration($configuration, static fn (): string => static::getUrl(
20	                $name,
21	                $parameters,
22	                $isAbsolute,
23	                $panel,
24	                $tenant,
25	                $shouldGuessMissingParameters,
26	                configuration: null,
27	            ));
28	        }
29	
30	        if ($shouldGuessMissingParameters) {
31	            $originalRequestRoute = null;
32	            $parentResources = [];
33	            $parentResource = static::getParentResourceRegistration();
34	
35	            while (filled($parentResource)) {
36	                array_unshift($parentResources, $parentResource);
37	
38	                $parentResource = $parentResource->getParentResource()::getParentResourceRegistration();
39	            }
40	
41	            foreach ($parentResources as $parentResource) {
42	                $parentRouteParameterName = $parentResource->getParentRouteParameterName();
43	
44	                if (filled($parameters[$parentRouteParameterName] ?? null)) {
45	                    continue;
46	                }
47	
48	                if (str(original_request()->getUri())->contains('/livewire-unit-test-endpoint/')) {
49	                    // In the future, Filament will support generating URLs for nested resources within tests.
50	                    // For now, it is unable to resolve the missing URL parameters from the parent records
51	                    // as it does not have access to the original request.
52	                    return '';
53	                }
54	
55	                $originalRequestRoute ??= original_request()->route();
56	
57	                if (! $originalRequestRoute->hasParameter($parentRouteParameterName)) {
58	                    $parameters[$parentRouteParameterName] = $originalRequestRoute->parameter('record');
59	
60	                    break;
61	                }
62	
63	                $parameters[$parentRouteParameterName] = $originalRequestRoute->parameter($parentRouteParameterName);
64	            }
65	        }
66	
67	        if (blank($name)) {
68	            return static::getIndexUrl($parameters, $isAbsolute, $panel, $tenant, $shouldGuessMissingParameters);
69	        }
70	
71	        if (blank($panel) || ($panel = Filament::getPanel($panel))->hasTenancy()) {
72	            $parameters['tenant'] ??= ($tenant ?? Filament::getTenant());
73	        }
74	
75	        $routeBaseName = static::getRouteBaseName($panel);
76	
77	        return route("{$routeBaseName}.{$name}", $parameters, $isAbsolute);
78	    }
79	
80	    /**
81	     * @param  array<mixed>  $parameters
82	     */
83	    public static function getIndexUrl(array $parameters = [], bool $isAbsolute = true, ?string $panel = null, ?Model $tenant = null, bool $shouldGuessMissingParameters = false): string
84	    {
85	        $parentResourceRegistration = static::getParentResourceRegistration();
86	
87	        if ($parentResourceRegistration) {
88	            $parentResource = $parentResourceRegistration->getParentResource();
89	            $parentRouteParameterName = $parentResourceRegistration->getParentRouteParameterName();
90	
91	            $record = $parameters[$parentRouteParameterName] ?? null;
92	            unset($parameters[$parentRouteParameterName]);
93	
94	            if ($parentResource::hasPage($relationshipPageName = $parentResourceRegistration->getRouteName())) {
95	                return $parentResource::getUrl($relationshipPageName, [
96	                    ...$parameters,
97	                    'record' => $record,
98	                ], $isAbsolute, $panel, $tenant, $shouldGuessMissingParameters);
99	            }
100	
101	            if ($parentResource::hasPage('view')) {
102	                return $parentResource::getUrl('view', [
103	                    'relation' => $parentResourceRegistration->getRelationshipName(),
104	                    ...$parameters,
105	                    'record' => $record,
106	                ], $isAbsolute, $panel, $tenant, $shouldGuessMissingParameters);
107	            }
108	
109	            if ($parentResource::hasPage('edit')) {
110	                return $parentResource::getUrl('edit', [
111	                    'relation' => $parentResourceRegistration->getRelationshipName(),
112	                    ...$parameters,
113	                    'record' => $record,
114	                ], $isAbsolute, $panel, $tenant, $shouldGuessMissingParameters);
115	            }
116	
117	            if ($parentResource::hasPage('index')) {
118	                return $parentResource::getUrl('index', $parameters, $isAbsolute, $panel, $tenant, $shouldGuessMissingParameters);
119	            }
120	        }
121	
122	        if (! static::hasPage('index')) {
123	            throw new LogicException('The resource [' . static::class . '] does not have an [index] page. Define [getIndexUrl()] for alternative routing.');
124	        }
125	
126	        return static::getUrl('index', $parameters, $isAbsolute, $panel, $tenant, $shouldGuessMissingParameters);
127	    }
128	}
