1	<?php
2	
3	namespace Filament\Resources\Resource\Concerns;
4	
5	use Closure;
6	use Filament\Facades\Filament;
7	use Filament\Panel;
8	use Filament\Resources\ResourceConfiguration;
9	use Illuminate\Database\Eloquent\Builder;
10	use Illuminate\Database\Eloquent\Model;
11	use Illuminate\Support\Facades\Route;
12	use Illuminate\Support\Stringable;
13	
14	/**
15	 * @template TModel of Model = Model
16	 */
17	trait HasRoutes
18	{
19	    protected static ?string $slug = null;
20	
21	    protected static ?string $recordRouteKeyName = null;
22	
23	    /**
24	     * @var string | array<string>
25	     */
26	    protected static string | array $routeMiddleware = [];
27	
28	    /**
29	     * @var string | array<string>
30	     */
31	    protected static string | array $withoutRouteMiddleware = [];
32	
33	    /**
34	     * @return Builder<TModel>
35	     */
36	    public static function getRecordRouteBindingEloquentQuery(): Builder
37	    {
38	        return static::getEloquentQuery();
39	    }
40	
41	    /**
42	     * @return ?TModel
43	     */
44	    public static function resolveRecordRouteBinding(int | string $key, ?Closure $modifyQuery = null): ?Model
45	    {
46	        $query = static::getRecordRouteBindingEloquentQuery();
47	
48	        if ($modifyQuery) {
49	            $query = $modifyQuery($query) ?? $query;
50	        }
51	
52	        return app(static::getModel())
53	            ->resolveRouteBindingQuery($query, $key, static::getRecordRouteKeyName())
54	            ->first();
55	    }
56	
57	    public static function getRouteBaseName(?Panel $panel = null): string
58	    {
59	        $panel ??= Filament::getCurrentOrDefaultPanel();
60	
61	        if ($parentResource = static::getParentResourceRegistration()) {
62	            return $parentResource->getParentResource()::getRouteBaseName($panel) . '.' . $parentResource->getRouteName();
63	        }
64	
65	        $routeBaseName = (string) str(static::getSlug($panel))
66	            ->replace('/', '.')
67	            ->prepend('resources.');
68	
69	        if (filled($cluster = static::getCluster())) {
70	            $routeBaseName = $cluster::prependClusterRouteBaseName($panel, $routeBaseName);
71	        }
72	
73	        return $panel->generateRouteName($routeBaseName);
74	    }
75	
76	    public static function getRecordRouteKeyName(): ?string
77	    {
78	        return static::$recordRouteKeyName;
79	    }
80	
81	    public static function routes(Panel $panel, ?Closure $registerPageRoutes = null): void
82	    {
83	        Route::name(static::getRelativeRouteName($panel) . '.')
84	            ->prefix(static::getRoutePrefix($panel))
85	            ->middleware(static::getRouteMiddleware($panel))
86	            ->withoutMiddleware(static::getWithoutRouteMiddleware($panel))
87	            ->group($registerPageRoutes);
88	    }
89	
90	    public static function registerRoutes(Panel $panel, ?Closure $registerPageRoutes = null, ?ResourceConfiguration $configuration = null): void
91	    {
92	        $registerPageRoutes ??= function () use ($panel, $configuration): void {
93	            foreach (static::getPages() as $name => $page) {
94	                $route = $page->registerRoute($panel);
95	
96	                if ($configuration) {
97	                    $route?->middleware("resource-configuration:{$configuration->getKey()}");
98	                }
99	
100	                $route?->name($name);
101	            }
102	        };
103	
104	        if ($parentResource = static::getParentResourceRegistration()) {
105	            $parentResource->getParentResource()::registerRoutes($panel, function () use ($panel, $parentResource, $registerPageRoutes): void {
106	                Route::name($parentResource->getRouteName() . '.')
107	                    ->prefix('{' . $parentResource->getParentRouteParameterName() . '}/' . static::getSlug($panel))
108	                    ->group($registerPageRoutes);
109	            });
110	
111	            return;
112	        }
113	
114	        $registerRoutes = fn () => static::routes($panel, $registerPageRoutes);
115	
116	        if (filled($cluster = static::getCluster())) {
117	            Route::name($cluster::prependClusterRouteBaseName($panel, 'resources.'))
118	                ->prefix($cluster::prependClusterSlug($panel, ''))
119	                ->group($registerRoutes);
120	
121	            return;
122	        }
123	
124	        Route::name('resources.')->group($registerRoutes);
125	    }
126	
127	    public static function getRelativeRouteName(Panel $panel): string
128	    {
129	        return (string) str(static::getSlug($panel))->replace('/', '.');
130	    }
131	
132	    public static function getRoutePrefix(Panel $panel): string
133	    {
134	        return static::getSlug($panel);
135	    }
136	
137	    /**
138	     * @return string | array<string>
139	     */
140	    public static function getRouteMiddleware(Panel $panel): string | array
141	    {
142	        return static::$routeMiddleware;
143	    }
144	
145	    /**
146	     * @return string | array<string>
147	     */
148	    public static function getWithoutRouteMiddleware(Panel $panel): string | array
149	    {
150	        return static::$withoutRouteMiddleware;
151	    }
152	
153	    public static function getEmailVerifiedMiddleware(Panel $panel): string
154	    {
155	        return $panel->getEmailVerifiedMiddleware();
156	    }
157	
158	    public static function getTenantSubscribedMiddleware(Panel $panel): string
159	    {
160	        return $panel->getTenantBillingProvider()->getSubscribedMiddleware();
161	    }
162	
163	    public static function getSlug(?Panel $panel = null): string
164	    {
165	        if ($configuration = static::getConfiguration($panel)) {
166	            if (filled($configSlug = $configuration->getSlug())) {
167	                return $configSlug;
168	            }
169	
170	            return static::getDefaultSlug() . '/' . $configuration->getKey();
171	        }
172	
173	        return static::getDefaultSlug();
174	    }
175	
176	    public static function getDefaultSlug(): string
177	    {
178	        if (filled(static::$slug)) {
179	            return static::$slug;
180	        }
181	
182	        $pluralBasenameBeforeResource = (string) str(static::class)
183	            ->classBasename()
184	            ->beforeLast('Resource')
185	            ->pluralStudly();
186	
187	        $namespacePartBeforeBasename = (string) str(static::class)
188	            ->beforeLast('\\')
189	            ->classBasename();
190	
191	        if ($pluralBasenameBeforeResource === $namespacePartBeforeBasename) {
192	            return str(static::class)
193	                ->beforeLast('\\')
194	                ->whenContains(
195	                    '\\Resources\\',
196	                    fn (Stringable $slug): Stringable => $slug->afterLast('\\Resources\\'),
197	                    fn (Stringable $slug): Stringable => $slug->classBasename(),
198	                )
199	                ->explode('\\')
200	                ->map(fn (string $string) => str($string)->kebab()->slug())
201	                ->implode('/');
202	        }
203	
204	        return str(static::class)
205	            ->whenContains(
206	                '\\Resources\\',
207	                fn (Stringable $slug): Stringable => $slug->afterLast('\\Resources\\'),
208	                fn (Stringable $slug): Stringable => $slug->classBasename(),
209	            )
210	            ->beforeLast('Resource')
211	            ->pluralStudly()
212	            ->explode('\\')
213	            ->map(fn (string $string) => str($string)->kebab()->slug())
214	            ->implode('/');
215	    }
216	}
