23	/**
24	 * Ricerca globale cross-collection (roadmap #23): i resource Filament
25	 * passano da Scout (driver "database" in test/dev) invece della LIKE di
26	 * default, così lo switch a Meilisearch non richiede di riscrivere questi
27	 * resource — vedi App\Filament\Concerns\HasScoutGlobalSearch.
28	 */
29	class GlobalSearchTest extends TestCase
30	{
31	    use RefreshDatabase;
32	
33	    protected function setUp(): void
34	    {
35	        parent::setUp();
36	
37	        // getGlobalSearchResultUrl() gate su canView/canEdit: serve un utente
38	        // autenticato, altrimenti Filament nega di default (nessuna policy).
39	        $this->actingAs(User::factory()->superAdmin()->create());
40	        Filament::setCurrentPanel('admin');
41	    }
42	
43	    public function test_product_resource_finds_records_via_scout(): void
44	    {
45	        $category1 = Category1::create(['name' => ['it' => 'Indoor']]);
46	        $category2 = Category2::create(['name' => ['it' => 'Collezione'], 'category_1_id' => $category1->id]);
47	        $productType = ProductType::create([
48	            'name' => ['it' => 'Tavolo'],
49	            'attribute_schema_class' => \App\Pim\Schemas\ProductAttributes::class,
50	        ]);
51	
52	        $product = Product::create([
53	            'name' => ['it' => 'Tavolino Kandy'],
54	            'category_2_id' => $category2->id,
55	            'product_type_id' => $productType->id,
56	        ]);
57	        Product::create([
58	            'name' => ['it' => 'Divano Modulare'],
59	            'category_2_id' => $category2->id,
60	            'product_type_id' => $productType->id,
61	        ]);
62	
63	        $results = ProductResource::getGlobalSearchResults('Kandy');
64	
65	        $this->assertCount(1, $results);
66	        $this->assertSame(ProductResource::getGlobalSearchResultUrl($product), $results->first()->url);
67	    }
68	
69	    public function test_material_resource_finds_records_via_scout_and_builds_nested_url(): void
70	    {
71	        $category = MaterialCategory::create(['name' => ['it' => 'Legni']]);
72	        $material = Material::create(['name' => ['it' => 'Ebano lucido'], 'material_category_id' => $category->id]);
73	        Material::create(['name' => ['it' => 'Vetro'], 'material_category_id' => $category->id]);
74	
75	        $results = MaterialResource::getGlobalSearchResults('Ebano');
76	
77	        $this->assertCount(1, $results);
78	        $this->assertSame(
79	            route('filament.admin.resources.material-categories.materials.index', [
80	                'category' => $category->getKey(),
81	                'tableAction' => 'edit',
82	                'tableActionRecord' => $material->getKey(),
83	            ]),
84	            $results->first()->url,
85	        );
86	    }
