91	        $fabric = Fabric::create(['name' => ['it' => 'Lino grezzo'], 'fabric_category_id' => $category->id]);
92	        Fabric::create(['name' => ['it' => 'Velluto blu'], 'fabric_category_id' => $category->id]);
93	
94	        $results = FabricResource::getGlobalSearchResults('Lino');
95	
