3	namespace Filament\Tables\Table\Concerns;
4	
5	use Closure;
6	use Illuminate\Database\Eloquent\Model;
7	use Illuminate\Support\Arr;
8	
9	trait HasRecordClasses
10	{
11	    /**
12	     * @var array<string | int, bool | string> | string | Closure | null
13	     */
14	    protected array | string | Closure | null $recordClasses = null;
15	
16	    /**
17	     * @param  array<string | int, bool | string> | string | Closure | null  $classes
18	     */
19	    public function recordClasses(array | string | Closure | null $classes): static
20	    {
21	        $this->recordClasses = $classes;
22	
23	        return $this;
24	    }
25	
26	    /**
27	     * @param  Model | array<string, mixed>  $record
28	     * @return array<string | int, bool | string>
29	     */
30	    public function getRecordClasses(Model | array $record): array
31	    {
32	        return Arr::wrap($this->evaluate(
33	            $this->recordClasses,
34	            namedInjections: [
35	                'record' => $record,
36	            ],
37	            typedInjections: ($record instanceof Model) ? [
38	                Model::class => $record,
39	                $record::class => $record,
40	            ] : [],
41	        ) ?? []);
42	    }
43	}
