3	namespace Filament\Tables\Concerns;
4	
5	use Filament\Tables\Enums\PaginationMode;
6	use Illuminate\Contracts\Pagination\CursorPaginator;
7	use Illuminate\Contracts\Pagination\Paginator;
8	use Illuminate\Database\Eloquent\Builder;
9	use Illuminate\Pagination\LengthAwarePaginator;
10	
11	trait CanPaginateRecords
12	{
13	    /**
14	     * @var int | string | null
15	     */
16	    public $tableRecordsPerPage = null;
17	
18	    protected int | string | null $defaultTableRecordsPerPageSelectOption = null;
19	
20	    public function updatedTableRecordsPerPage(): void
21	    {
22	        session()->put([
23	            $this->getTablePerPageSessionKey() => $this->getTableRecordsPerPage(),
24	        ]);
25	
26	        $this->resetPage();
27	    }
28	
29	    protected function paginateTableQuery(Builder $query): Paginator | CursorPaginator
30	    {
31	        $perPage = $this->getTableRecordsPerPage();
32	
33	        $mode = $this->getTable()->getPaginationMode();
34	
35	        if ($mode === PaginationMode::Simple) {
36	            return $query->simplePaginate(
37	                perPage: ($perPage === 'all') ? $query->toBase()->getCountForPagination() : $perPage,
38	                pageName: $this->getTablePaginationPageName(),
39	            );
40	        }
41	
42	        if ($mode === PaginationMode::Cursor) {
43	            return $query->cursorPaginate(
44	                perPage: ($perPage === 'all') ? $query->toBase()->getCountForPagination() : $perPage,
45	                cursorName: $this->getTablePaginationPageName(),
46	            );
47	        }
48	
49	        $total = $query->toBase()->getCountForPagination();
50	
51	        /** @var LengthAwarePaginator $records */
52	        $records = $query->paginate(
53	            perPage: ($perPage === 'all') ? $total : $perPage,
54	            pageName: $this->getTablePaginationPageName(),
55	            total: $total,
56	        );
57	
58	        return $records->onEachSide(0);
59	    }
60	
61	    public function getTableRecordsPerPage(): int | string | null
62	    {
63	        return $this->tableRecordsPerPage;
64	    }
65	
66	    public function getTablePage(): int | string
67	    {
68	        return $this->getPage($this->getTablePaginationPageName());
69	    }
70	
71	    public function getDefaultTableRecordsPerPageSelectOption(): int | string
72	    {
73	        $option = session()->get(
74	            $this->getTablePerPageSessionKey(),
75	            $this->defaultTableRecordsPerPageSelectOption ?? $this->getTable()->getDefaultPaginationPageOption(),
76	        );
77	
78	        $pageOptions = $this->getTable()->getPaginationPageOptions();
79	
80	        if (in_array($option, $pageOptions)) {
81	            return $option;
82	        }
83	
84	        session()->remove($this->getTablePerPageSessionKey());
85	
86	        return $pageOptions[0];
87	    }
88	
89	    public function getTablePaginationPageName(): string
90	    {
91	        return $this->getIdentifiedTableQueryStringPropertyNameFor('page');
92	    }
93	
94	    public function getTablePerPageSessionKey(): string
95	    {
96	        $table = md5($this::class);
97	
98	        return "tables.{$table}_per_page";
99	    }
100	
101	    /**
102	     * @deprecated Override the `table()` method to configure the table.
103	     *
104	     * @return array<int | string> | null
105	     */
106	    protected function getTableRecordsPerPageSelectOptions(): ?array
107	    {
108	        return null;
109	    }
110	
111	    /**
112	     * @deprecated Override the `table()` method to configure the table.
113	     */
114	    protected function isTablePaginationEnabled(): bool
115	    {
116	        return true;
117	    }
118	}
