12	use Illuminate\Pagination\LengthAwarePaginator;
13	use Illuminate\Support\Collection;
14	use LogicException;
15	
16	use function Livewire\invade;
17	
18	trait HasRecords
19	{
20	    /**
21	     * @deprecated Override the `table()` method to configure the table.
22	     */
23	    protected bool $allowsDuplicates = false;
24	
25	    protected Collection | Paginator | CursorPaginator | null $cachedTableRecords = null;
26	
27	    public function getFilteredTableQuery(): ?Builder
28	    {
29	        $query = $this->getTable()->getQuery();
30	
31	        if (! $query) {
32	            return null;
33	        }
34	
35	        return $this->filterTableQuery($query);
36	    }
37	
38	    public function filterTableQuery(Builder $query): Builder
39	    {
40	        $this->applyFiltersToTableQuery($query);
41	
42	        $this->applySearchToTableQuery($query);
43	
44	        foreach ($this->getTable()->getVisibleColumns() as $column) {
45	            $column->applyRelationshipAggregates($query);
46	
47	            if ($this->getTable()->isGroupsOnly()) {
48	                continue;
49	            }
50	
51	            $column->applyEagerLoading($query);
52	        }
53	
54	        return $query;
55	    }
56	
57	    public function getFilteredSortedTableQuery(): ?Builder
58	    {
59	        $query = $this->getFilteredTableQuery();
60	
61	        if (! $query) {
62	            return null;
63	        }
64	
65	        $this->applyGroupingToTableQuery($query);
66	
67	        $this->applySortingToTableQuery($query);
68	
69	        return $query;
70	    }
71	
72	    public function getTableQueryForExport(): Builder
73	    {
74	        $query = $this->getTable()->getQuery();
75	
76	        $this->applyFiltersToTableQuery($query);
77	        $this->applySearchToTableQuery($query);
78	        $this->applySortingToTableQuery($query);
79	
80	        return $query;
81	    }
82	
83	    protected function hydratePivotRelationForTableRecords(EloquentCollection | Paginator | CursorPaginator $records): EloquentCollection | Paginator | CursorPaginator
84	    {
85	        $table = $this->getTable();
86	        $relationship = $table->getRelationship();
87	
88	        if ($table->getRelationship() instanceof BelongsToMany && ! $table->allowsDuplicates()) {
89	            invade($relationship)->hydratePivotRelation($records->all());
90	        }
91	
92	        return $records;
93	    }
94	
95	    public function getTableRecords(): Collection | Paginator | CursorPaginator
96	    {
97	        if (! $this->getTable()->hasQuery()) {
98	            if ($this->cachedTableRecords) {
99	                return $this->cachedTableRecords;
100	            }
101	
102	            $records = $this->getTable()->evaluate($this->getTable()->getDataSource(), [
103	                'columnSearches' => fn (): array => $this->getTableColumnSearches(),
104	                'filters' => fn (): ?array => $this->tableFilters,
105	                'page' => fn (): int | string => $this->getTablePage(),
106	                'recordsPerPage' => fn (): int | string => $this->getTableRecordsPerPage(),
107	                'search' => fn (): ?string => $this->getTableSearch(),
108	                'sort' => fn (): array => [$this->getTableSortColumn(), $this->getTableSortDirection()],
109	                'sortColumn' => fn (): ?string => $this->getTableSortColumn(),
110	                'sortDirection' => fn (): ?string => $this->getTableSortDirection(),
111	            ]);
112	
113	            if (is_array($records)) {
114	                $collection = collect($records);
115	            } elseif (
116	                ($records instanceof Paginator || $records instanceof CursorPaginator) &&
117	                method_exists($records, 'getCollection')
118	            ) {
119	                $collection = $records->getCollection();
120	            } else {
121	                $collection = $records;
122	            }
