3	namespace Livewire\Features\SupportPagination;
4	
5	use Illuminate\Pagination\Paginator;
6	use Illuminate\Support\Str;
7	
8	trait HandlesPagination
9	{
10	    public $paginators = [];
11	
12	    public function queryStringHandlesPagination()
13	    {
14	        return collect($this->paginators)->mapWithKeys(function ($page, $pageName) {
15	            return ['paginators.'.$pageName => ['history' => true, 'as' => $pageName, 'keep' => false]];
16	        })->toArray();
17	    }
18	
19	    public function getPage($pageName = 'page')
20	    {
21	        return $this->paginators[$pageName] ?? Paginator::resolveCurrentPage($pageName);
22	    }
23	
24	    public function previousPage($pageName = 'page')
25	    {
26	        $this->setPage(max(($this->paginators[$pageName] ?? 1) - 1, 1), $pageName);
27	    }
28	
29	    public function nextPage($pageName = 'page')
30	    {
31	        $this->setPage(($this->paginators[$pageName] ?? 1) + 1, $pageName);
32	    }
33	
34	    public function gotoPage($page, $pageName = 'page')
35	    {
36	        $this->setPage($page, $pageName);
37	    }
38	
39	    public function resetPage($pageName = 'page')
40	    {
41	        $this->setPage(1, $pageName);
42	    }
43	
44	    public function setPage($page, $pageName = 'page')
45	    {
46	        if (is_numeric($page)) {
47	            $page = (int) ($page <= 0 ? 1 : $page);
48	        }
49	
50	        $beforePaginatorMethod = 'updatingPaginators';
51	        $afterPaginatorMethod = 'updatedPaginators';
52	
53	        $beforeMethod = 'updating' . ucfirst(Str::camel($pageName));
54	        $afterMethod = 'updated' . ucfirst(Str::camel($pageName));
55	
56	        if (method_exists($this, $beforePaginatorMethod)) {
57	            $this->{$beforePaginatorMethod}($page, $pageName);
58	        }
59	
60	        if (method_exists($this, $beforeMethod)) {
61	            $this->{$beforeMethod}($page, null);
62	        }
63	
64	        $this->paginators[$pageName] = $page;
65	
66	        if (method_exists($this, $afterPaginatorMethod)) {
67	            $this->{$afterPaginatorMethod}($page, $pageName);
68	        }
69	
70	        if (method_exists($this, $afterMethod)) {
71	            $this->{$afterMethod}($page, null);
72	        }
73	    }
74	}
