3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Filament\Concerns;
6	
7	use Filament\Actions\Action;
8	use Filament\Actions\CreateAction;
9	use Filament\Support\Icons\Heroicon;
10	use Override;
11	
12	trait IsDigitalHubListPage
13	{
14	    /**
15	     * Evita di rieseguire il salto pagina (sotto) a ogni interazione Livewire
16	     * successiva al mount iniziale — altrimenti bloccherebbe la paginazione
17	     * normale, riportando l'utente alla pagina del record cercato ogni volta.
18	     */
19	    public bool $hasJumpedToHighlightedTableRecordPage = false;
20	
21	    #[Override]
22	    protected function getHeaderActions(): array
23	    {
24	        return [
25	            $this->getSortAction(),
26	            $this->getNewAction(),
27	        ];
28	    }
29	
30	    /**
31	     * Se l'URL porta `tableActionRecord` (click da un risultato di ricerca
32	     * globale, roadmap #23, o refresh di un'azione già aperta) e il record
33	     * non è nella pagina corrente della tabella, salta alla pagina che lo
34	     * contiene — altrimenti l'evidenziazione della riga
35	     * (`DigitalHubTableMacro::apply()` → `recordClasses()`) non ha nessuna
36	     * riga visibile su cui applicarsi.
37	     *
38	     * Hook `booted*` (non `mount*`): lo stato di filtri/ordinamento/per-page
39	     * persistito in sessione è risolto da
40	     * `InteractsWithTable::bootedInteractsWithTable()`, un hook "booted"
41	     * anch'esso — gira prima del nostro perché dichiarato dalla classe base,
42	     * quindi qui `getTableRecordsPerPage()` è già risolto. A differenza dei
43	     * `mount*` (solo al primo caricamento), i `booted*` girano a ogni
44	     * richiesta Livewire: da qui il flag di guardia sopra.
45	     */
46	    public function bootedIsDigitalHubListPage(): void
47	    {
48	        if ($this->hasJumpedToHighlightedTableRecordPage) {
49	            return;
50	        }
51	
52	        $this->hasJumpedToHighlightedTableRecordPage = true;
53	
54	        $highlightedKey = request()->query('tableActionRecord');
55	        fwrite(STDERR, 'DEBUG highlightedKey: ' . var_export($highlightedKey, true) . "\n");
56	
57	        if (! is_string($highlightedKey)) {
58	            return;
59	        }
60	
61	        $perPage = $this->getTableRecordsPerPage();
62	        fwrite(STDERR, 'DEBUG perPage: ' . var_export($perPage, true) . "\n");
63	
64	        if (! is_numeric($perPage)) {
65	            // 'all' o non ancora risolto: nessuna paginazione da saltare.
66	            return;
67	        }
68	
69	        $query = $this->getFilteredSortedTableQuery();
70	        fwrite(STDERR, 'DEBUG query null: ' . var_export($query === null, true) . "\n");
71	
72	        if ($query === null) {
73	            return;
74	        }
75	
76	        $position = $query->pluck($query->getModel()->getKeyName())
77	            ->map(fn (mixed $key): string => is_scalar($key) ? (string) $key : '')
78	            ->search($highlightedKey);
79	        fwrite(STDERR, 'DEBUG position: ' . var_export($position, true) . "\n");
80	
81	        if ($position === false) {
82	            return;
83	        }
84	
85	        $page = intdiv((int) $position, (int) $perPage) + 1;
86	        fwrite(STDERR, 'DEBUG page: ' . var_export($page, true) . "\n");
87	
88	        $this->setPage($page, $this->getTablePaginationPageName());
89	    }
90	
91	    /**
92	     * New action for "list" pages
93	     */
94	    protected function getNewAction(): CreateAction
95	    {
96	        return CreateAction::make()
97	            ->icon(Heroicon::Plus)
98	            ->slideOver()
99	            ->modalHeading(__('digital-hub::common.create_heading'))
100	        ;
101	    }
102	
103	    protected function getSortAction(): Action
104	    {
105	        return Action::make('sort')
106	            ->visible(
107	                fn () => $this->getAllTableRecordsCount() > 1
108	                &&
109	                $this->getTable()->isReorderable(),
110	            )
111	            ->action('toggleTableReordering')
112	            ->label(function () {
113	                return $this->getTable()->isReordering() ? __('digital-hub::common.save_order') : __('digital-hub::common.edit_order');
114	            })
115	            ->icon(function () {
116	                return $this->getTable()->isReordering() ? Heroicon::Check : Heroicon::ArrowsUpDown;
117	            })
118	            ->color('gray')
119	            ->button()
120	            ->outlined();
121	    }
122	
123	
124	}
