3	declare(strict_types=1);
4	
5	namespace Tests\Feature\Search;
6	
7	use App\Filament\Resources\Products\Pages\ListProducts;
8	use App\Models\Category1;
9	use App\Models\Category2;
10	use App\Models\Product;
11	use App\Models\ProductType;
12	use App\Models\User;
13	use AtrioTeam\DigitalHub\Pim\Filament\Tables\DigitalHubTableMacro;
14	use Filament\Facades\Filament;
15	use Illuminate\Foundation\Testing\RefreshDatabase;
16	use Livewire\Livewire;
17	use Tests\TestCase;
18	
19	/**
20	 * Atterrando su una tabella da un risultato di ricerca globale (roadmap
21	 * #23) l'URL contiene `?tableAction=edit&tableActionRecord=<id>` (Livewire
22	 * `#[Url]`, apre anche l'action modal). La riga corrispondente riceve uno
23	 * sfondo evidenziato — `DigitalHubTableMacro::apply()` — per essere
24	 * individuata visivamente nell'elenco, non solo nella modale.
25	 */
26	class SearchResultRowHighlightTest extends TestCase
27	{
28	    use RefreshDatabase;
29	
30	    protected function setUp(): void
31	    {
32	        parent::setUp();
33	
34	        // registrato normalmente dal boot del DigitalHubPlugin, che nei test
35	        // Livewire non viene eseguito
36	        DigitalHubTableMacro::register();
37	    }
38	
39	    public function test_the_record_matching_the_url_query_string_is_highlighted(): void
40	    {
41	        $this->actingAs(User::factory()->superAdmin()->create());
42	        Filament::setCurrentPanel('admin');
43	
44	        $category1 = Category1::create(['name' => ['it' => 'Indoor']]);
45	        $category2 = Category2::create(['name' => ['it' => 'Collezione'], 'category_1_id' => $category1->id]);
46	        $productType = ProductType::create([
47	            'name' => ['it' => 'Tavolo'],
48	            'attribute_schema_class' => \App\Pim\Schemas\ProductAttributes::class,
49	        ]);
50	
51	        $highlighted = Product::create(['name' => ['it' => 'Tavolino Kandy'], 'category_2_id' => $category2->id, 'product_type_id' => $productType->id]);
52	        $other = Product::create(['name' => ['it' => 'Divano Modulare'], 'category_2_id' => $category2->id, 'product_type_id' => $productType->id]);
53	
54	        $table = Livewire::test(ListProducts::class)->instance()->getTable();
55	
56	        // getRecordClasses() legge request() al momento della chiamata (è così
57	        // anche a runtime, dentro il render della tabella): impostarla dopo
58	        // Livewire::test() replica lo stesso momento del ciclo di vita reale.
59	        app()->instance('request', \Illuminate\Http\Request::create('/admin/products', 'GET', [
60	            'tableActionRecord' => (string) $highlighted->getKey(),
61	        ]));
62	
63	        $this->assertContains('!bg-warning-50 dark:!bg-warning-400/10', $table->getRecordClasses($highlighted));
64	        $this->assertSame([], $table->getRecordClasses($other));
65	    }
66	
67	    public function test_no_record_is_highlighted_without_the_query_string(): void
68	    {
69	        $this->actingAs(User::factory()->superAdmin()->create());
70	        Filament::setCurrentPanel('admin');
71	
72	        $category1 = Category1::create(['name' => ['it' => 'Indoor']]);
73	        $category2 = Category2::create(['name' => ['it' => 'Collezione'], 'category_1_id' => $category1->id]);
74	        $productType = ProductType::create([
75	            'name' => ['it' => 'Tavolo'],
76	            'attribute_schema_class' => \App\Pim\Schemas\ProductAttributes::class,
77	        ]);
78	        $product = Product::create(['name' => ['it' => 'Tavolino Kandy'], 'category_2_id' => $category2->id, 'product_type_id' => $productType->id]);
79	
80	        $table = Livewire::test(ListProducts::class)->instance()->getTable();
81	
82	        $this->assertSame([], $table->getRecordClasses($product));
83	    }
84	}
