1	<?php
2	
3	namespace AtrioTeam\DigitalHub\Pim\Filament\Tables;
4	
5	use Filament\Actions\ActionGroup;
6	use Filament\Actions\BulkActionGroup;
7	use Filament\Actions\DeleteAction;
8	use Filament\Actions\DeleteBulkAction;
9	use Filament\Actions\EditAction;
10	use Filament\Support\Enums\Width;
11	use Filament\Tables\Columns\Column;
12	use Filament\Tables\Columns\TextColumn;
13	use Filament\Tables\Table;
14	use Illuminate\Database\Eloquent\Model;
15	
16	class DigitalHubTableMacro
17	{
18	    public static function register(): void
19	    {
20	        // register a macro to perform some customization on all tables of the Digital Hub, like adding a default record action to open the edit page
21	        Table::macro('digitalHubTable', function (array $recordActions = []): Table {
22	            // $this is bound to the Table instance at runtime by Laravel's Macroable;
23	            // PHPStan cannot infer this statically for a macro closure.
24	            /** @var Table $this */
25	            // @phpstan-ignore-next-line varTag.variableNotFound, variable.undefined, argument.type
26	            return DigitalHubTableMacro::apply($this, $recordActions);
27	        });
28	    }
29	
30	    /**
31	     * Apply the Digital Hub customizations to a table.
32	     *
33	     * @param array<\Filament\Actions\Action> $recordActions Azioni di riga extra,
34	     *                                                       anteposte all'ActionGroup standard (es. ManageAssetsAction).
35	     */
36	    public static function apply(Table $table, array $recordActions = []): Table
37	    {
38	        $table->recordActions([
39	            ...$recordActions,
40	            ActionGroup::make([
41	                EditAction::make()->slideOver()->modalWidth(Width::ScreenTwoExtraLarge),
42	                DeleteAction::make(),
43	            ]),
44	        ])
45	        ->toolbarActions([
46	            BulkActionGroup::make([
47	                DeleteBulkAction::make()
48	                    ->modalHeading(__('digital-hub::common.delete_confirmation')),
49	            ]),
50	        ])
51	        ->defaultSort('sort')
52	        ->reorderable('sort')
53	        // evidenzia la riga il cui action modal (edit/view) è aperto via URL
54	        // (?tableAction=…&tableActionRecord=…, Livewire #[Url]): copre sia il
55	        // click da un risultato di ricerca globale (roadmap #23) sia il refresh
56	        // di una pagina con un'azione già aperta.
57	        ->recordClasses(function (Model $record): ?string {
58	            $highlightedKey = request()->query('tableActionRecord');
59	            $recordKey = $record->getKey();
60	
61	            if (! is_string($highlightedKey) || ! is_scalar($recordKey)) {
62	                return null;
63	            }
64	
65	            return ((string) $recordKey === $highlightedKey)
66	                ? '!bg-warning-50 dark:!bg-warning-400/10'
67	                : null;
68	        })
69	        ;
70	
71	        // customize filters
72	        $filters = $table->getFilters();
73	        if (count($filters) > 2) {
74	            $table->filtersFormColumns(3);
75	        }
76	
77	        // $table->filters($filters,);
78	
79	
80	        // convert the created_at column to proper timezone and format if it exists
81	        collect($table->getColumns())->each(function (Column $column): void {
82	            if ($column instanceof TextColumn && $column->getName() === 'created_at') {
83	                $column->dateTime('d/m/Y H:i', 'Europe/Rome')->sortable()->toggleable(isToggledHiddenByDefault: true);
84	            }
85	        });
86	
87	        return $table;
88	    }
89	}
