3	declare(strict_types=1);
4	
5	namespace App\Filament\Resources\Products\Schemas;
6	
7	use App\Models\Category2;
8	use App\Models\Environment;
9	use App\Models\Fabric;
10	use App\Models\FabricCategory;
11	use App\Models\Material;
12	use App\Models\MaterialCategory;
13	use App\Models\Product;
14	use App\Models\ProductType;
15	use App\Pim\Filament\Schemas\Category1Select;
16	use AtrioTeam\DigitalHub\Filament\Forms\Components\NestedCheckboxSelect;
17	use AtrioTeam\DigitalHub\Pim\AttributeSchema;
18	use AtrioTeam\DigitalHub\Pim\Filament\Schemas\AttributesEditorSection;
19	use AtrioTeam\DigitalHub\Pim\Filament\Schemas\NameAndId;
20	use AtrioTeam\DigitalHub\Pim\Filament\Schemas\OrphanAttributesAlert;
21	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
22	use AtrioTeam\DigitalHub\Tags\Filament\TagPicker;
23	use Filament\Forms\Components\Select;
24	use Filament\Infolists\Components\TextEntry;
25	use Filament\Schemas\Components\Section;
26	use Filament\Schemas\Components\Utilities\Get;
27	use Filament\Schemas\Schema;
28	use Filament\Support\Enums\TextSize;
29	
30	class ProductForm
31	{
32	    public static function configure(Schema $schema): Schema
33	    {
34	        return $schema
35	            ->components([
36	                // solo informativo: per i prodotti la destinazione è stabilita
37	                // dalla categoria padre della collezione selezionata
38	                Category1Select::section(
39	                    TextEntry::make('category1_info')
40	                        ->hiddenLabel()
41	                        ->state(function (Get $get): string {
42	                            $categoryId = $get('category_2_id');
43	
44	                            if (! is_numeric($categoryId)) {
45	                                return '—';
46	                            }
47	
48	                            return Category2::query()->find((int) $categoryId)?->category1->name ?? '—';
49	                        })
50	                        ->size(TextSize::Large)
51	                        ->badge(),
52	                ),
53	                NameAndId::make($schema),
54	
55	                Section::make(__('product.sections.classification'))
56	                    ->columns(2)
57	                    ->schema([
58	                        Select::make('category_2_id')
59	                            ->label(__('product.category_2'))
60	                            ->options(fn (): array => Category2::query()->pluck('name', 'id')->map(fn (mixed $name): string => is_scalar($name) ? (string) $name : '')->all())
61	                            ->default(fn (): mixed => request()->query('category_2'))
62	                            ->required()
63	                            ->searchable()
64	                            // reattivo: aggiorna il campo informativo "Destinazione"
65	                            ->live(),
66	                        Select::make('parent_id')
67	                            ->label(__('product.parent'))
68	                            ->helperText(__('product.parent_helper'))
69	                            // gerarchia a un solo livello: candidati padre sono solo i prodotti
70	                            // senza padre a loro volta; escluso il record stesso in edit
71	                            ->options(fn (?Product $record): array => Product::query()
72	                                ->whereNull('parent_id')
73	                                ->when($record !== null, fn ($query) => $query->whereKeyNot($record?->getKey()))
74	                                ->with('category2')
75	                                ->orderBy('name->it')
76	                                ->get()
77	                                ->mapWithKeys(fn (Product $parent): array => [
78	                                    $parent->id => $parent->catalogName(),
79	                                ])
80	                                ->all())
81	                            ->searchable()
82	                            // un wrapper con moduli non può a sua volta avere un padre
83	                            ->hidden(fn (?Product $record): bool => $record !== null && $record->modules()->exists()),
84	                        Select::make('product_type_id')
85	                            ->label(__('product.product_type'))
86	                            ->options(fn (): array => ProductType::query()->pluck('name', 'id')->map(fn (mixed $name): string => is_scalar($name) ? (string) $name : '')->all())
87	                            ->required()
88	                            ->searchable()
89	                            // reattivo: il cambio di tipologia rigenera l'editor degli attributi
90	                            // e (ri)valuta l'alert orfani sottostante
91	                            ->live(),
92	                        Select::make('environments')
93	                            ->label(__('product.environments'))
94	                            ->relationship('environments', 'name')
95	                            ->options(fn (): array => Environment::query()->pluck('name', 'id')->map(fn (mixed $name): string => is_scalar($name) ? (string) $name : '')->all())
96	                            ->multiple()
97	                            ->searchable()
98	                            ->preload(),
99	                    ]),
100	                Section::make(__('product.sections.materials_fabrics'))
101	                    ->columns(2)
102	                    ->schema([
103	                        // checkbox annidati per categoria: la relazione è salvata
104	                        // sempre a livello di singolo materiale/tessuto
105	                        NestedCheckboxSelect::make('materials')
106	                            ->label(__('material.model_plural'))
107	                            ->relationship('materials', Material::class, MaterialCategory::class, 'material_category_id', __('material.no_category')),
108	                        NestedCheckboxSelect::make('fabrics')
109	                            ->label(__('fabric.model_plural'))
110	                            ->relationship('fabrics', Fabric::class, FabricCategory::class, 'fabric_category_id', __('fabric.no_category')),
111	                    ]),
112	
113	                // solo i tag dei gruppi (product, entity) — vincolo rigido
114	                TagPicker::make((new Product())->getMorphClass(), TagTarget::Entity),
115	
116	
117	                // alert orfani: avvisa, al cambio tipologia, dei valori PIM che si
118	                // perderebbero perché non più previsti dal nuovo schema (vedi core).
119	                OrphanAttributesAlert::reactive($schema, self::schemaResolver()),
120	
121	                // la section "Dati tecnici" (con le tabs per gruppo) è renderizzata
122	                // direttamente dal componente
123	                AttributesEditorSection::reactive($schema, self::schemaResolver())->columnSpanFull(),
124	
125	            ]);
126	    }
127	
128	    /**
129	     * Resolver dello schema attributi corrente dal form state: legge
130	     * product_type_id e ritorna la AttributeSchema della tipologia selezionata
131	     * (o null). Condiviso da AttributesEditorSection::reactive() e OrphanAttributesAlert.
132	     *
133	     * @return \Closure(Get): ?AttributeSchema
134	     */
135	    private static function schemaResolver(): \Closure
136	    {
137	        return static function (Get $get): ?AttributeSchema {
138	            $class = self::schemaClassFor($get('product_type_id'));
139	
140	            return $class !== null ? new $class() : null;
141	        };
142	    }
143	
144	    /**
145	     * FQN della AttributeSchema associata a una tipologia, o null se non risolvibile.
146	     *
147	     * @return class-string<AttributeSchema>|null
148	     */
149	    private static function schemaClassFor(mixed $productTypeId): ?string
150	    {
151	        if (! is_numeric($productTypeId)) {
152	            return null;
153	        }
154	
155	        $class = ProductType::query()->find((int) $productTypeId)?->attribute_schema_class;
156	
157	        return is_string($class) && is_subclass_of($class, AttributeSchema::class) ? $class : null;
158	    }
159	}
