3	namespace AtrioTeam\DigitalHub\Pim\Filament\Schemas;
4	
5	use AtrioTeam\DigitalHub\Pim\Filament\Actions\TranslateActionModal;
6	use Closure;
7	use Filament\Actions\Action;
8	use Filament\Actions\ActionGroup;
9	use Filament\Schemas\Components\Component;
10	use Filament\Schemas\Components\Tabs;
11	use Illuminate\Contracts\Support\Htmlable;
12	use Illuminate\Contracts\View\View;
13	
14	class TranslationSection extends Tabs
15	{
16	    /**
17	     * @var array<string,string> $locales the locales to create tabs for [locale => label]
18	     */
19	    protected array $locales;
20	
21	
22	    /**
23	     * List of components to be added to the tabs
24	     * @var array<Component | Action | ActionGroup | string | Htmlable> | Closure
25	     */
26	    protected array|Closure $sourceComponents = [];
27	
28	    /**
29	     * @var callable|null $configureUsing
30	     *                    Callback to configure the component
31	     */
32	    protected static $configureUsing;
33	
34	    /**
35	     * @var Closure|null $tabsModifier optional callback to configure the internal Tabs component
36	     */
37	    protected ?Closure $tabsModifier = null;
38	
39	    /**
40	     * @var bool $enableAutoTranslation if true, the auto-translation feature via DeepL will be enabled
41	     */
42	    protected bool $enableAutoTranslation = false;
43	
44	
45	    /**
46	     * @param array<Component | Action | ActionGroup | string | Htmlable> | Closure $components
47	     */
48	    public function schema(array | Closure $components): static
49	    {
50	        $this->sourceComponents = $components;
51	
52	        $this->build();
53	
54	        return $this;
55	    }
56	
57	
58	    /**
59	     * Set the locales for the tabs
60	     * @param array<string,string> $locales
61	     */
62	    public function locales(array $locales): self
63	    {
64	        $this->locales = $locales;
65	        return $this;
66	    }
67	
68	
69	    /**
70	     * Configure the internal Tabs component via a callback.
71	     * The callback receives the Tabs instance and can call any method on it.
72	     *
73	     * Usage: ->modifyTabsUsing(fn (Tabs $tabs) => $tabs->contained(false))
74	     *
75	     * Nota: poiché TranslationSection estende Tabs, la closure riceve $this e si
76	     * potrebbero chiamare i metodi direttamente sull'istanza (es. ->contained(false)).
77	     * Per i metodi idempotenti che impostano una semplice property le due strade sono
78	     * equivalenti (la chiamata diretta resta valida, $this è sempre lo stesso oggetto).
79	     * Questo metodo serve solo quando la modifica deve avvenire DOPO la (ri)costruzione
80	     * dei tab: la closure viene infatti ri-eseguita a ogni build(), sempre dopo ->tabs(),
81	     * utile p.es. per toccare i singoli Tab già creati o per configurare l'istanza al
82	     * make() (via configureUsing) quando i tab ancora non esistono.
83	     */
84	    public function modifyTabsUsing(Closure $callback): static
85	    {
86	        $this->tabsModifier = $callback;
87	
88	        $this->build();
89	
90	        return $this;
91	    }
92	
93	    /**
94	     * Enable the auto-translation feature: adds a "Traduci" hint action (DeepL,
95	     * via {@see TranslateActionModal}) on text-like fields, to fill the other
96	     * locales from the current one.
97	     */
98	    public function autoTranslation(bool $enable = true): static
99	    {
100	        $this->enableAutoTranslation = $enable;
101	
102	        $this->build();
103	
104	        return $this;
105	    }
106	
107	    /**
108	     * Set the required locales for the tabs
109	     */
110	    /*  public function requiredLocales(array $requiredLocales): self
111	     {
112	         $this->requiredLocales = $requiredLocales;
113	         return $this;
114	     } */
115	
116	
117	    /**
118	     * Transform the tabs into a schema
119	     */
120	    protected function build(): self
121	    {
122	        // I setter (autoTranslation/modifyTabsUsing/schema) chiamano build() ma
123	        // l'impostazione resta memorizzata nelle property: le tab si costruiscono
124	        // solo quando i locale sono noti. Così configureUsing() può abilitare
125	        // autoTranslation() al make(), prima di ->locales(), senza accedere a
126	        // $locales non inizializzato; il build effettivo avviene poi da ->schema().
127	        if (! isset($this->locales)) {
128	            return $this;
129	        }
130	
131	        /*  if (count($this->locales) == 1) {
132	             $this->childComponents([
133	                 SingleLocaleTab::make('')
134	                     ->label('')
135	                     ->schema(
136	                         $this->buildTab(key($this->locales)),
137	                     ),
138	             ]);
139	
140	             return $this;
141	         } */
142	
143	        $tabs = [];
144	        foreach ($this->locales as $locale => $label) {
145	
146	            $tabSchema = $this->buildTab($locale);
147	
148	            $tabs[] = Tabs\Tab::make($label . strtoupper($locale))
149	                ->label(count($this->locales) > 1 ? strtoupper($label) : '')
150	                ->schema(
151	                    $tabSchema,
152	                );
153	        }
154	
155	        $this->columnSpanFull()->tabs($tabs);
156	
157	        if ($this->tabsModifier) {
158	            ($this->tabsModifier)($this);
159	        }
160	
161	        return $this;
162	
163	    }
164	
165	
166	    /**
167	     * Create the schema for a single tab in a single locale.
168	     * Returns an array of components included in the tab
169	     * @return array<string,Component> $components
170	     */
171	    protected function buildTab(string $locale): array
172	    {
173	        $fieldsGroup = [];
174	
175	        /**
176	         * @var array<string,Component> $fields
177	         */
178	        $fields = is_callable($this->sourceComponents) ? call_user_func($this->sourceComponents) : $this->sourceComponents;
179	        foreach ($fields as $component) {
180	
181	            $clone = $component->getClone();
182	
183	            /** @var string $originalName */
184	            // @phpstan-ignore method.notFound
185	            $originalName = $component->getName();
186	
187	            // $clone->label("{$component->getLabel()} ({$locale})");
188	
189	            $name = $originalName . '.' . $locale;
190	
191	            // set a meta so that locale can be accessed in the component
192	            // see e.g. the required() method in the TextInput component
193	            $clone->meta('locale', $locale);
194	
195	            // @phpstan-ignore method.notFound
196	            $clone->name($name);
197	            $clone->statePath($name);
198	
199	            // auto-traduzione DeepL: hint action solo sui campi testuali e solo
200	            // se ci sono più locale (con un solo locale non c'è nulla da tradurre)
201	            if ($this->enableAutoTranslation && count($this->locales) > 1 && in_array(get_class($clone), [
202	                \Filament\Forms\Components\TextInput::class,
203	                \Filament\Forms\Components\Textarea::class,
204	                \Filament\Forms\Components\RichEditor::class,
205	                \Filament\Forms\Components\MarkdownEditor::class,
206	            ], true)) {
207	                $clone->hintAction(
208	                    TranslateActionModal::make($name, $locale, $this->locales),
209	                );
210	            }
211	
212	            $fieldsGroup[$name] = $clone;
213	
214	        }
215	
216	        return $fieldsGroup;
217	    }
218	
219	
220	    public function render(): View
221	    {
222	        /**
223	         * single-locale: la nav delle tab viene nascosta via CSS
224	         * (vedi digital-hub-custom.scss → .digital-hub-translation-section.single-locale)
225	         */
226	        /** @var array<string, string> $extraAttributes */
227	        $extraAttributes = $this->getExtraAttributes();
228	
229	        $extraAttributes['class'] ??= '';
230	        $extraAttributes['class'] .= ' digital-hub-translation-section';
231	
232	        if (count($this->locales) <= 1) {
233	            $extraAttributes['class'] .= ' single-locale';
234	        }
235	
236	        $this->extraAttributes($extraAttributes);
237	
238	
239	        return parent::render();
240	    }
241	
