3	namespace AtrioTeam\DigitalHub\Pim\Filament\Tables;
4	
5	use Filament\Actions\ActionGroup;
6	use Filament\Actions\BulkActionGroup;
7	use Filament\Actions\DeleteAction;
8	use Filament\Actions\DeleteBulkAction;
9	use Filament\Actions\EditAction;
10	use Filament\Actions\ViewAction;
11	use Filament\Support\Enums\Width;
12	use Filament\Tables\Columns\Column;
13	use Filament\Tables\Columns\TextColumn;
14	use Filament\Tables\Table;
15	use Illuminate\Database\Eloquent\Model;
16	
17	class DigitalHubTableMacro
18	{
19	    public static function register(): void
20	    {
21	        // register a macro to perform some customization on all tables of the Digital Hub, like adding a default record action to open the edit page
22	        Table::macro('digitalHubTable', function (array $recordActions = []): Table {
23	            // $this is bound to the Table instance at runtime by Laravel's Macroable;
24	            // PHPStan cannot infer this statically for a macro closure.
25	            /** @var Table $this */
26	            // @phpstan-ignore-next-line varTag.variableNotFound, variable.undefined, argument.type
27	            return DigitalHubTableMacro::apply($this, $recordActions);
28	        });
29	    }
30	
31	    /**
32	     * Apply the Digital Hub customizations to a table.
33	     *
34	     * @param array<\Filament\Actions\Action> $recordActions Azioni di riga extra,
35	     *                                                       anteposte all'ActionGroup standard (es. ManageAssetsAction).
36	     */
37	    public static function apply(Table $table, array $recordActions = []): Table
38	    {
39	        $table->recordActions([
40	            ...$recordActions,
41	            ActionGroup::make([
42	                ViewAction::make()->slideOver()->modalWidth(Width::ScreenTwoExtraLarge),
43	                EditAction::make()->slideOver()->modalWidth(Width::ScreenTwoExtraLarge),
44	                DeleteAction::make(),
45	            ]),
46	        ])
47	        ->toolbarActions([
48	            BulkActionGroup::make([
49	                DeleteBulkAction::make()
50	                    ->modalHeading(__('digital-hub::common.delete_confirmation')),
51	            ]),
52	        ])
53	        ->defaultSort('sort')
54	        ->reorderable('sort')
55	        // evidenzia la riga il cui action modal (edit/view) è aperto via URL
56	        // (?tableAction=…&tableActionRecord=…, Livewire #[Url]): copre sia il
57	        // click da un risultato di ricerca globale (roadmap #23) sia il refresh
58	        // di una pagina con un'azione già aperta.
59	        ->recordClasses(function (Model $record): ?string {
60	            $highlightedKey = request()->query('tableActionRecord');
61	            $recordKey = $record->getKey();
62	
63	            if (! is_string($highlightedKey) || ! is_scalar($recordKey)) {
64	                return null;
65	            }
66	
67	            return ((string) $recordKey === $highlightedKey)
68	                ? '!bg-warning-50 dark:!bg-warning-400/10'
69	                : null;
70	        })
71	        ;
72	
73	        // customize filters
74	        $filters = $table->getFilters();
75	        if (count($filters) > 2) {
76	            $table->filtersFormColumns(3);
77	        }
78	
79	        // $table->filters($filters,);
80	
81	
82	        // convert the created_at column to proper timezone and format if it exists
83	        collect($table->getColumns())->each(function (Column $column): void {
84	            if ($column instanceof TextColumn && $column->getName() === 'created_at') {
85	                $column->dateTime('d/m/Y H:i', 'Europe/Rome')->sortable()->toggleable(isToggledHiddenByDefault: true);
86	            }
87	        });
88	
89	        return $table;
90	    }
91	}
