3	namespace Filament\Actions\Concerns;
4	
5	use BackedEnum;
6	use Closure;
7	use Illuminate\Auth\Access\Response;
8	use Illuminate\Database\Eloquent\Model;
9	use Illuminate\Support\Arr;
10	use Illuminate\Support\Facades\Gate;
11	use LogicException;
12	use UnitEnum;
13	
14	trait CanBeAuthorized
15	{
16	    // Security: Actions do not have automatic policy-based authorization.
17	    // Authorization defaults to `null` (allowed for all users).
18	    // You must explicitly use `authorize()`, `visible()`, or
19	    // `hidden()` to restrict access to custom actions.
20	
21	    protected mixed $authorization = null;
22	
23	    protected string | Closure | null $authorizationMessage = null;
24	
25	    protected bool | Closure $hasAuthorizationTooltip = false;
26	
27	    protected bool | Closure $hasAuthorizationNotification = false;
28	
29	    protected bool | string | UnitEnum | Closure | null $authorizeIndividualRecords = null;
30	
31	    /**
32	     * @param  Model | class-string | array<mixed> | null  $arguments
33	     */
34	    public function authorize(mixed $abilities, Model | string | array | null $arguments = null): static
35	    {
36	        $abilities = match (true) {
37	            $abilities instanceof BackedEnum => $abilities->value,
38	            $abilities instanceof UnitEnum => $abilities->name,
39	            default => $abilities,
40	        };
41	
42	        if (is_string($abilities) || is_array($abilities)) {
43	            $this->authorization = [
44	                'type' => 'all',
45	                'abilities' => Arr::wrap($abilities),
46	                'arguments' => Arr::wrap($arguments),
47	            ];
48	        } else {
49	            $this->authorization = $abilities;
50	        }
51	
52	        return $this;
53	    }
54	
55	    /**
56	     * @param  string | UnitEnum | array<string | UnitEnum>  $abilities
57	     * @param  Model | array<mixed> | null  $arguments
58	     */
59	    public function authorizeAny(string | UnitEnum | array $abilities, Model | array | null $arguments = null): static
60	    {
61	        $abilities = match (true) {
62	            $abilities instanceof BackedEnum => $abilities->value,
63	            $abilities instanceof UnitEnum => $abilities->name,
64	            default => $abilities,
65	        };
66	
67	        $this->authorization = [
68	            'type' => 'any',
69	            'abilities' => Arr::wrap($abilities),
70	            'arguments' => Arr::wrap($arguments),
71	        ];
72	
73	        return $this;
74	    }
75	
76	    /**
77	     * @param  array<mixed>  $arguments
78	     * @return array<mixed>
79	     */
80	    protected function parseAuthorizationArguments(array $arguments): array
81	    {
82	        if ($record = $this->getRecord()) {
83	            array_unshift($arguments, $record);
84	        } elseif ($model = $this->getModel()) {
85	            array_unshift($arguments, $model);
86	        }
87	
88	        return $arguments;
89	    }
90	
91	    public function isAuthorized(): bool
92	    {
93	        if ($this->authorization === null) {
94	            return $this->getHasActionsLivewire()?->getDefaultActionAuthorizationResponse($this)?->allowed() ?? true;
95	        }
96	
97	        if (! is_array($this->authorization)) {
98	            $response = $this->evaluate($this->authorization);
99	
100	            return match (true) {
101	                $response instanceof Response => $response->allowed(),
102	                default => (bool) $response,
103	            };
104	        }
105	
106	        $abilities = $this->authorization['abilities'] ?? [];
107	        $arguments = $this->parseAuthorizationArguments($this->authorization['arguments'] ?? []);
108	        $type = $this->authorization['type'] ?? null;
109	
110	        return match ($type) {
111	            'all' => Gate::check($abilities, $arguments),
112	            'any' => Gate::any($abilities, $arguments),
113	            default => false,
114	        };
115	    }
116	
117	    public function getAuthorizationResponse(): Response
118	    {
119	        if ($this->authorization === null) {
120	            return $this->getHasActionsLivewire()->getDefaultActionAuthorizationResponse($this) ?? Response::allow();
121	        }
122	
123	        if (! is_array($this->authorization)) {
124	            $response = $this->evaluate($this->authorization);
125	
126	            return match (true) {
127	                $response instanceof Response => $response,
128	                (bool) $response => Response::allow(),
129	                default => Response::deny(),
130	            };
131	        }
132	
133	        $abilities = $this->authorization['abilities'] ?? [];
134	        $arguments = $this->parseAuthorizationArguments($this->authorization['arguments'] ?? []);
135	        $type = $this->authorization['type'] ?? null;
136	
137	        foreach ($abilities as $ability) {
138	            $response = Gate::inspect($ability, Arr::wrap($arguments));
139	
140	            if (($type === 'any') && $response->allowed()) {
141	                return $response;
142	            }
143	
144	            if (($type === 'all') && $response->denied()) {
145	                return $response;
146	            }
147	        }
148	
149	        return Response::allow();
150	    }
151	
152	    public function getAuthorizationResponseWithMessage(): Response
153	    {
154	        $response = $this->getAuthorizationResponse();
155	
156	        if ($response->allowed()) {
157	            return $response;
158	        }
159	
160	        $message = $this->getAuthorizationMessage();
161	
162	        if (filled($message)) {
163	            invade($response)->message = $message; /** @phpstan-ignore-line */
164	
165	            return $response;
166	        }
167	
168	        if (blank($response->message())) {
169	            throw new LogicException('An authorization was denied without a message.');
170	        }
171	
172	        return $response;
173	    }
174	
175	    public function authorizationMessage(string | Closure | null $message): static
176	    {
177	        $this->authorizationMessage = $message;
178	
179	        return $this;
180	    }
181	
182	    public function getAuthorizationMessage(): ?string
183	    {
184	        return $this->evaluate($this->authorizationMessage);
185	    }
186	
187	    public function authorizationTooltip(bool | Closure $condition = true): static
188	    {
189	        $this->hasAuthorizationTooltip = $condition;
190	
191	        return $this;
192	    }
193	
194	    public function authorizationNotification(bool | Closure $condition = true): static
195	    {
196	        $this->hasAuthorizationNotification = $condition;
197	
198	        return $this;
199	    }
200	
201	    public function hasAuthorizationTooltip(): bool
202	    {
203	        return (bool) $this->evaluate($this->hasAuthorizationTooltip);
204	    }
205	
206	    public function hasAuthorizationNotification(): bool
207	    {
208	        return (bool) $this->evaluate($this->hasAuthorizationNotification);
209	    }
210	
211	    public function isAuthorizedOrNotHiddenWhenUnauthorized(): bool
212	    {
213	        if (! $this->hasAuthorizationTooltip() && ! $this->hasAuthorizationNotification()) {
214	            return $this->isAuthorized();
215	        }
216	
217	        $response = $this->getAuthorizationResponse();
218	
219	        if ($response->allowed()) {
220	            return true;
221	        }
222	
223	        return filled($response->message()) || filled($this->getAuthorizationMessage());
224	    }
225	
226	    public function authorizeIndividualRecords(bool | string | UnitEnum | Closure | null $callback = true): static
227	    {
228	        $this->authorizeIndividualRecords = $callback;
229	
230	        return $this;
231	    }
232	
233	    public function getIndividualRecordAuthorizationResponse(Model $record): Response
234	    {
235	        if (is_string($this->authorizeIndividualRecords) || ($this->authorizeIndividualRecords instanceof UnitEnum)) {
236	            return Gate::inspect($this->authorizeIndividualRecords, Arr::wrap($record));
237	        }
238	
239	        $resolver = ($this->authorizeIndividualRecords instanceof Closure)
240	            ? $this->authorizeIndividualRecords
241	            : $this->getHasActionsLivewire()->getDefaultActionIndividualRecordAuthorizationResponseResolver($this);
242	
243	        if (! $resolver) {
244	            throw new LogicException('No function was passed to [authorizeIndividualRecords()].');
245	        }
246	
247	        $response = $resolver($record);
248	
249	        if ($response instanceof Response) {
250	            return $response;
251	        }
252	
253	        return $response ? Response::allow() : Response::deny();
254	    }
255	
256	    public function shouldAuthorizeIndividualRecords(): bool
257	    {
258	        return filled($this->authorizeIndividualRecords) && ($this->authorizeIndividualRecords !== false);
259	    }
260	}
