    /**
     * Pulsante "Modifica" nel footer della modale view (`extraModalFooterActions`
     * su `ViewAction`, `DigitalHubTableMacro::apply()`): azione nidificata
     * indipendente che apre la modale edit sullo stesso record, impilata
     * sopra la view (non la sostituisce). Nome di default 'edit' invariato:
     * eredita la stessa autorizzazione automatica della riga, nessun codice
     * di autorizzazione duplicato qui.
     */
    public function test_view_modal_footer_edit_action_opens_a_nested_editable_modal_for_the_same_record(): void
    {
        $this->actingAs(User::factory()->superAdmin()->create());
        Filament::setCurrentPanel('admin');

        $category1 = Category1::create(['name' => ['it' => 'Indoor']]);
        $category2 = Category2::create(['name' => ['it' => 'Collezione'], 'category_1_id' => $category1->id]);
        $productType = ProductType::create([
            'name' => ['it' => 'Divano'],
            'attribute_schema_class' => \App\Pim\Schemas\ProductAttributes::class,
        ]);
        $materialCategory = MaterialCategory::create(['name' => ['it' => 'Legni']]);
        $oak = Material::create(['name' => ['it' => 'Rovere'], 'material_category_id' => $materialCategory->id]);
        $product = Product::create([
            'name' => ['it' => 'Prodotto vista'],
            'category_2_id' => $category2->id,
            'product_type_id' => $productType->id,
        ]);
        $product->materials()->attach($oak->id);

        $instance = Livewire::test(ListProducts::class)
            ->mountTableAction(['view', 'edit'], $product)
            ->instance();

        $this->assertCount(2, $instance->mountedActions);
        $this->assertSame('view', $instance->mountedActions[0]['name']);
        $this->assertSame('edit', $instance->mountedActions[1]['name']);

        $nestedField = $instance->getSchema('mountedActionSchema1')
            ->getFlatComponents(withActions: false, withHidden: true)['materials'];

        $this->assertSame([(string) $oak->id], $nestedField->getState());
        $this->assertFalse($nestedField->isDisabled());
    }
}

